window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-53254017b22220a9"]={"versions": [{"id": "FIG-53254017b22220a9", "releases": ["R20-11", "R21-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Statisches Standard-Abhängigkeitsdiagramm / Schichtenmodell auf Spezifikationsebene (Informelles Blockdiagramm).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Visualisiert die normative Abhängigkeitsstruktur der AUTOSAR-Hauptstandards. Definiert das Foundation-Konzept: Sowohl die <strong>Classic Platform (CP)</strong> als auch die <strong>Adaptive Platform (AP)</strong> basieren architektonisch und normativ auf dem gemeinsamen Standard <strong>Foundation (FO)</strong>. Die Foundation bündelt plattformübergreifende Anforderungen, standardisierte Kommunikations- und Diagnoseprotokolle sowie das gemeinsame Metamodell-Fundament für ARXML.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten (Standard-Domänen):</strong>\n<ul class=\"fig-list\"><li><code>Foundation</code>: Basis-Spezifikationspaket. Definiert plattformneutrale Grundlagen, darunter:\n<ul class=\"fig-list\"><li>Protokollspezifikationen (z. B. SOME/IP, SOME/IP-SD, DoIP, UDS).\n</li><li>Sicherheits- und Schutzmechanismen (z. B. E2E-Protection-Profile, SecOC-Algorithmen, TLS-Profile).\n</li><li>Gemeinsames AUTOSAR-Metamodell (Base Infrastructure, allgemeine Blueprint-Mechanismen, grundlegende Datentypen).\n</li></ul>\n</li><li><code>Classic Platform</code>: Echtzeit- und mikrocontrollerorientierte Plattform (statische Konfiguration, C-APIs, BSW-Schichtenmodell, MCAL, RTE, deterministisches OSEK-basiertes OS).\n</li><li><code>Adaptive Platform</code>: Hochleistungs- und POSIX-orientierte Plattform (dynamische Service-Orientierte Architektur [SOA], C++-APIs <code>ara::*</code>, <code>ara::exec</code>, <code>ara::com</code>, Multi-Core/64-Bit-MPUs).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><code>Classic Platform ➔ Foundation</code>: Unidirektionale Spezifikationsabhängigkeit. CP referenziert und implementiert die in der Foundation definierten Protokolle (z. B. SOME/IP via <code>SomeIpXf</code>/<code>SoAd</code>) und Metamodell-Definitionen.\n</li><li><code>Adaptive Platform ➔ Foundation</code>: Unidirektionale Spezifikationsabhängigkeit. AP referenziert dieselben Foundation-Standards (z. B. <code>ara::com</code>-SOME/IP-Bindings, DoIP-Diagnose).\n</li><li><code>Classic Platform ⟷ Adaptive Platform</code>: <strong>Keine direkte funktionale oder spezifikatorische Abhängigkeit.</strong> CP und AP sind voneinander entkoppelt; Interoperabilität auf Fahrzeugnetzwerkebene existiert ausschließlich über die durch die Foundation vereinheitlichten Wire-Formate und Protokolle.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statische Spezifikationshierarchie).</strong>\n</li><li><em>Architektonische Laufzeit-Konsequenz:</em> Bei der Inter-Plattform-Kommunikation (z. B. CP-ECU kommuniziert via Ethernet mit AP-HPC) existiert kein shared memory oder API-Aufruf; der Austausch erfolgt über das in der Foundation definierte Wire-Format (z. B. SOME/IP Payload Serialization, E2E Data Transformation) über Netzwerk-Interfaces.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Release-Kompatibilität &amp; Synchronisation:</strong>\n<ul class=\"fig-list\"><li>CP- und AP-Releases (z. B. R20-11, R21-11, R23-11, R24-11) setzen immer auf dem korrespondierenden Foundation-Release auf. Ein Mismatch der Plattform-Releases kann zu Inkompatibilitäten bei Serialisierung (z. B. String-Handling, Alignment-Regeln in SOME/IP) oder Metamodell-Versionen führen.\n</li></ul>\n</li><li><strong>Metamodell &amp; ARXML-Datenaustausch:</strong>\n<ul class=\"fig-list\"><li>System-Beschreibungen (System Description) nutzen Foundation-Pakete zur Deklaration geteilter Daten (z. B. Service Interfaces, Datentypen, Topologie). Modellanpassungen in der Foundation wirken sich direkt auf BSW-Generatoren (CP) und Manifest-Compiler (AP) aus.\n</li></ul>\n</li><li><strong>Protokoll- &amp; Treiber-Entwicklung:</strong>\n<ul class=\"fig-list\"><li>Für Stack-Entwickler (z. B. Ethernet-, SOME/IP- oder Diagnose-Stacks) sind Spezifikationen aus der Foundation (<code>PRS</code>-Dokumente wie <code>AUTOSAR_PRS_SOMEIPProtocol</code>) primär verbindlich, nicht plattformspezifische SWS-Dokumente allein.\n</li><li>CP-Transformatoren (<code>SomeIpXf</code>) und AP-Kommunikations-Backends (<code>ara::com</code> Binding) müssen bitgenau gegen dieselbe Foundation-Protokoll-Baseline implementiert und validiert werden, um Interoperabilität sicherzustellen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cb01b1700fe35957", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Statisches Standard-Abhängigkeitsdiagramm / Schichtenmodell auf Spezifikationsebene (Informelles Blockdiagramm).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Visualisiert die normative Abhängigkeitsstruktur der AUTOSAR-Hauptstandards. Definiert das Foundation-Konzept: Sowohl die <strong>Classic Platform (CP)</strong> als auch die <strong>Adaptive Platform (AP)</strong> basieren architektonisch und normativ auf dem gemeinsamen Standard <strong>Foundation (FO)</strong>. Die Foundation bündelt plattformübergreifende Anforderungen, standardisierte Kommunikations- und Diagnoseprotokolle sowie das gemeinsame Metamodell-Fundament für ARXML.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten (Standard-Domänen):</strong>\n<ul class=\"fig-list\"><li><code>Foundation</code>: Basis-Spezifikationspaket. Definiert plattformneutrale Grundlagen, darunter:\n<ul class=\"fig-list\"><li>Protokollspezifikationen (z. B. SOME/IP, SOME/IP-SD, DoIP, UDS).\n</li><li>Sicherheits- und Schutzmechanismen (z. B. E2E-Protection-Profile, SecOC-Algorithmen, TLS-Profile).\n</li><li>Gemeinsames AUTOSAR-Metamodell (Base Infrastructure, allgemeine Blueprint-Mechanismen, grundlegende Datentypen).\n</li></ul>\n</li><li><code>Classic Platform</code>: Echtzeit- und mikrocontrollerorientierte Plattform (statische Konfiguration, C-APIs, BSW-Schichtenmodell, MCAL, RTE, deterministisches OSEK-basiertes OS).\n</li><li><code>Adaptive Platform</code>: Hochleistungs- und POSIX-orientierte Plattform (dynamische Service-Orientierte Architektur [SOA], C++-APIs <code>ara::*</code>, <code>ara::exec</code>, <code>ara::com</code>, Multi-Core/64-Bit-MPUs).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><code>Classic Platform ➔ Foundation</code>: Unidirektionale Spezifikationsabhängigkeit. CP referenziert und implementiert die in der Foundation definierten Protokolle (z. B. SOME/IP via <code>SomeIpXf</code>/<code>SoAd</code>) und Metamodell-Definitionen.\n</li><li><code>Adaptive Platform ➔ Foundation</code>: Unidirektionale Spezifikationsabhängigkeit. AP referenziert dieselben Foundation-Standards (z. B. <code>ara::com</code>-SOME/IP-Bindings, DoIP-Diagnose).\n</li><li><code>Classic Platform ⟷ Adaptive Platform</code>: <strong>Keine direkte funktionale oder spezifikatorische Abhängigkeit.</strong> CP und AP sind voneinander entkoppelt; Interoperabilität auf Fahrzeugnetzwerkebene existiert ausschließlich über die durch die Foundation vereinheitlichten Wire-Formate und Protokolle.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statische Spezifikationshierarchie).</strong>\n</li><li><em>Architektonische Laufzeit-Konsequenz:</em> Bei der Inter-Plattform-Kommunikation (z. B. CP-ECU kommuniziert via Ethernet mit AP-HPC) existiert kein shared memory oder API-Aufruf; der Austausch erfolgt über das in der Foundation definierte Wire-Format (z. B. SOME/IP Payload Serialization, E2E Data Transformation) über Netzwerk-Interfaces.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Release-Kompatibilität &amp; Synchronisation:</strong>\n<ul class=\"fig-list\"><li>CP- und AP-Releases (z. B. R20-11, R21-11, R23-11, R24-11) setzen immer auf dem korrespondierenden Foundation-Release auf. Ein Mismatch der Plattform-Releases kann zu Inkompatibilitäten bei Serialisierung (z. B. String-Handling, Alignment-Regeln in SOME/IP) oder Metamodell-Versionen führen.\n</li></ul>\n</li><li><strong>Metamodell &amp; ARXML-Datenaustausch:</strong>\n<ul class=\"fig-list\"><li>System-Beschreibungen (System Description) nutzen Foundation-Pakete zur Deklaration geteilter Daten (z. B. Service Interfaces, Datentypen, Topologie). Modellanpassungen in der Foundation wirken sich direkt auf BSW-Generatoren (CP) und Manifest-Compiler (AP) aus.\n</li></ul>\n</li><li><strong>Protokoll- &amp; Treiber-Entwicklung:</strong>\n<ul class=\"fig-list\"><li>Für Stack-Entwickler (z. B. Ethernet-, SOME/IP- oder Diagnose-Stacks) sind Spezifikationen aus der Foundation (<code>PRS</code>-Dokumente wie <code>AUTOSAR_PRS_SOMEIPProtocol</code>) primär verbindlich, nicht plattformspezifische SWS-Dokumente allein.\n</li><li>CP-Transformatoren (<code>SomeIpXf</code>) und AP-Kommunikations-Backends (<code>ara::com</code> Binding) müssen bitgenau gegen dieselbe Foundation-Protokoll-Baseline implementiert und validiert werden, um Interoperabilität sicherzustellen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-53254017b22220a9", "to": "FIG-cb01b1700fe35957", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
